var o=`1386-moksi-alesi`;var n=`world-1386`;var t=`SR`;var s=`south-america`;var a=4;var r=54;var l={en:`Moksi Alesi`,ua:`Моксі алесі`};var d={en:`Moksi Alesi is a dish from Suriname featuring white rice, yellow onion, garlic, smoked pork loin. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Моксі алесі, страва кухні країни Суринам з такими основними складниками: білий рис, жовта цибуля, часник, копчена свиняча корейка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`white-rice`,430,`g`],[`water`,680,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`smoked-pork-loin`,200,`g`],[`canola-oil`,35,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`shrimp`,310,`g`],[`chicken-thigh`,390,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`light-soy-sauce`,40,`ml`],[`green-onion`,28,`g`]]}];var m={slug:o,id:n,country:`SR`,region:s,servings:4,minutes:54,title:l,text:d,steps:u};export{t as country,m as default,n as id,r as minutes,s as region,a as servings,o as slug,u as steps,d as text,l as title};